    #[test]
    fn pages_reflect_unsaved_rotation_edits() {
        let mut s = session(pdf_with_info());
        assert_eq!(s.pages().unwrap()[0].rotate, 0);
        s.set_page_rotation(0, 270).unwrap();
        assert_eq!(s.pages().unwrap()[0].rotate, 270);
        s.undo();
        assert_eq!(s.pages().unwrap()[0].rotate, 0);
    }

    #[test]
    fn the_base_document_is_never_mutated() {
        // The retained buffer and the parsed graph are what verbatim
        // re-emission depends on; an edit that touched them would break
        // §5 for every OTHER object in the file.
        let bytes = pdf_with_info();
        let mut s = session(bytes.clone());
        s.set_page_rotation(0, 90).unwrap();
        s.set_info_field(InfoField::Title, Some("Changed")).unwrap();
        assert_eq!(s.document().bytes(), bytes.as_slice());
        let page = s.document().get(ObjId::new(3, 0)).unwrap();
        assert!(page.value.as_dict().unwrap().get(b"Rotate").is_none());
    }

    #[test]
    fn undo_history_is_bounded_without_affecting_the_diff() {
        // Overflowing the stack must cost history, never correctness:
        // the dirty set is a diff, not a replay.
        let mut s = session(pdf_with_info());
        for i in 0..(MAX_UNDO_DEPTH + 10) {
            s.set_info_field(InfoField::Title, Some(&format!("v{i}")))
                .unwrap();
        }
        assert_eq!(s.undo_depth(), MAX_UNDO_DEPTH);
        assert_eq!(s.dirty_set().len(), 1);
        assert_eq!(
            s.info_text(InfoField::Title).unwrap().text,
            format!("v{}", MAX_UNDO_DEPTH + 9)
        );
    }

    #[test]
    fn undo_and_redo_return_what_they_moved() {
        let mut s = session(pdf_with_info());
        s.set_page_rotation(0, 90).unwrap();
        assert_eq!(
            s.undo_kind(),
            Some(CommandKind::SetPageRotation {
                page_index: 0,
                degrees: 90
            })
        );
        assert_eq!(s.undo(), s.redo_kind());
        assert!(s.redo().is_some());
        assert!(s.redo().is_none());
    }

    #[test]
    fn text_strings_round_trip_through_both_encodings() {
        for text in ["Plain ASCII", "Café", "日本語", ""] {
            let encoded = encode_text_string(text);
            let decoded = decode_text_string(&encoded);
            assert_eq!(decoded.text, text, "round trip failed for {text:?}");
            assert!(decoded.exact, "round trip was inexact for {text:?}");
        }
    }

    #[test]
    fn latin_text_uses_the_pdfdoc_table_and_only_the_untabled_takes_the_bom() {
        // ★ THIS TEST ASSERTED THE OPPOSITE UNTIL `Pass 150.0`, and it was
        // right to: it characterised a DEFERRAL, not a design. Its previous
        // body was
        //
        //     assert_eq!(encode_text_string("é").first(), Some(&0xFE));
        //
        // i.e. "anything non-ASCII takes the UTF-16BE BOM form", which was
        // true while this module had no PDFDocEncoding table. `textstring`
        // has had one in both directions for some time; the deferral expired
        // and nobody came back to it, because a comment naming a reason reads
        // as settled.
        assert_eq!(encode_text_string("Report 2026"), b"Report 2026".to_vec());
        // `é` IS in the Annex D.3 table, so it is one byte, not a BOM string.
        assert_eq!(encode_text_string("é"), vec![0xE9]);
        // Something genuinely outside the table still takes UTF-16BE.
        assert_eq!(encode_text_string("日").first(), Some(&0xFE));
    }

    #[test]
    fn the_byte_where_pdfdoc_and_latin1_disagree_now_decodes_from_the_table() {
        // ★ REWRITTEN BY `Pass 150.0`. It read:
        //
        //   "0x91 is where PDFDocEncoding and Latin-1 disagree, and the
        //    PDFDocEncoding table is a recorded spec-RAG gap. Guessing would
        //    be silently wrong; U+FFFD plus `exact: false` is visibly
        //    incomplete, which a front end can act on."
        //
        // The ARGUMENT was sound and is preserved by the fix rather than
        // discarded: guessing Latin-1 for 0x91 would be silently wrong. The
        // answer was never to guess — it was to use the real table, which
        // `textstring` now has, and which decodes this byte exactly.
        // ★ The VALUE is asserted, not just "no replacement character". The
        // doctest on `decode_text_string` first claimed 0x91 was U+2018 —
        // guessed from memory while writing about the table's arrival, which
        // is precisely the failure the old text warned against. It is U+201A
        // (SINGLE LOW-9); U+2018 is 0x8F. Read from
        // `textstring::PDF_DOC_ENCODING`, not recalled.
        let decoded = decode_text_string(&[b'A', 0x91, b'B']);
        assert!(decoded.exact, "the table decodes it exactly now");
        assert_eq!(decoded.text, "A\u{201A}B");
        assert!(
            !decoded.text.contains('\u{FFFD}'),
            "and no replacement character is produced: {:?}",
            decoded.text
        );

        // An odd-length UTF-16BE body is malformed, and says so.
        assert!(!decode_text_string(&[0xFE, 0xFF, 0x00]).exact);
    }

    #[test]
    fn normalize_rotation_uses_a_positive_modulo() {
        // Rust's `%` keeps the dividend's sign, so a naive
        // implementation yields -90 here and every renderer downstream
        // sees a rotation it does not expect.
        assert_eq!(normalize_rotation(-90), 270);
        assert_eq!(normalize_rotation(-450), 270);
        assert_eq!(normalize_rotation(360), 0);
        assert_eq!(normalize_rotation(0), 0);
        // A malformed non-multiple floors to the enclosing quarter turn.
        assert_eq!(normalize_rotation(100), 90);
    }

    #[test]
    fn info_fields_all_have_distinct_keys() {
        let mut keys: Vec<&[u8]> = InfoField::all().iter().map(|f| f.key()).collect();
        keys.sort_unstable();
        let before = keys.len();
        keys.dedup();
        assert_eq!(keys.len(), before);
        // R41: /Producer is deliberately NOT editable here.
        assert!(!keys.contains(&&b"Producer"[..]));
    }

    // -- Pass 6.1 annotation authoring ---------------------------------

    use crate::annot_author::{Color, MarkupSpec, TextMarkupKind};
    use crate::page_tree::Rect;

    /// A square spec on a fixed rect, the simplest authoring case.
    fn square_spec() -> MarkupSpec {
        MarkupSpec::Square {
            rect: Rect {
                llx: 20.0,
                lly: 20.0,
                urx: 120.0,
                ury: 70.0,
            },
            border: Some(Color::Rgb(1.0, 0.0, 0.0)),
            interior: None,
            border_width: 2.0,
            border_effect: None,
        }
    }

    // -- set_markup_style: restyling a PLACED annotation ---------------

    /// The `/AP` `/N` stream id an annotation currently points at.
    fn ap_of(s: &EditSession, annot_id: ObjId) -> Option<ObjId> {
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            return None;
        };
        let Some(Object::Dict(ap)) = annot.get(b"AP") else {
            return None;
        };
        ap.get(b"N").and_then(Object::as_reference)
    }

    /// Seed an object's value directly, bypassing the command log.
    /// **Fixture setup only** — it exists so a test can shape an
    /// annotation the way a foreign producer would have (a `/NM`, a
    /// shared `/AP`, a `/Locked` flag) without a second authoring verb.
    fn poke(s: &mut EditSession, id: ObjId, value: Object) {
        s.state.insert(id, value);
    }

    /// The raw appearance-stream bytes an annotation currently points at,
    /// resolved against the session's staging buffer.
    fn ap_bytes(s: &EditSession, ap_id: ObjId) -> Vec<u8> {
        let Some(Object::Stream(st)) = s.value(ap_id) else {
            return Vec::new();
        };
        let src = s.authored_source();
        st.data_span
            .slice(src.as_ref())
            .map(<[u8]>::to_vec)
            .unwrap_or_default()
    }

    /// The raw `/C` numbers on an annotation.
    fn color_of(s: &EditSession, annot_id: ObjId) -> Vec<f64> {
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            return Vec::new();
        };
        match annot.get(b"C") {
            Some(Object::Array(items)) => items.iter().filter_map(Object::as_number).collect(),
            _ => Vec::new(),
        }
    }

    #[test]
    fn restyling_keeps_the_annotation_and_appearance_object_ids() {
        // The headline contract, and the whole reason this is not
        // delete-and-re-add: the annotation object survives, so its /NM,
        // its /Annots index (paint order) and any /IRT reply thread hung
        // off it survive with it.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let ap_before = ap_of(&s, annot_id).expect("authored AP");
        let annots_before = s.value(ObjId::new(3, 0)).cloned();

        let change = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();

        assert_eq!(change.annot_id, annot_id, "same object id");
        assert_eq!(change.appearance, AppearanceWrite::InPlace(ap_before));
        assert_eq!(ap_of(&s, annot_id), Some(ap_before), "same AP object");
        assert_eq!(
            s.value(ObjId::new(3, 0)).cloned(),
            annots_before,
            "the page (and so /Annots order, and so z-order) is untouched"
        );
        assert_eq!(color_of(&s, annot_id), vec![0.0, 0.0, 1.0]);
    }

    #[test]
    fn restyling_regenerates_the_appearance_not_just_the_dictionary() {
        // R43 paints from /AP or not at all. A verb that set /C and left
        // the appearance drawing the old colour would pass a naive
        // dictionary assertion while doing NOTHING the operator can see.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let ap_id = ap_of(&s, annot_id).expect("AP");
        let bytes_before = ap_bytes(&s, ap_id);
        assert!(
            !bytes_before.is_empty(),
            "the authored AP must have content"
        );

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                ..MarkupStyle::default()
            },
        )
        .unwrap();

        let bytes_after = ap_bytes(&s, ap_id);
        assert_ne!(
            bytes_before, bytes_after,
            "the appearance stream must change, or the edit is invisible"
        );
        // The red the square was authored with is gone from the content.
        assert!(
            !String::from_utf8_lossy(&bytes_after).contains("1 0 0 RG")
                && String::from_utf8_lossy(&bytes_after).contains("RG"),
            "the new stroke colour must be in the appearance: {}",
            String::from_utf8_lossy(&bytes_after)
        );
    }

    #[test]
    fn restyling_preserves_every_key_it_does_not_own() {
        // /NM, /T, /Contents, /IRT, /M, /F, /P — the identity-adjacent
        // keys a re-add would lose. Written onto the annotation directly
        // so the test does not depend on `add_markup` authoring them.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            panic!("annot");
        };
        let mut seeded = annot.clone();
        for (k, v) in [
            (&b"NM"[..], Object::String(b"comment-7".to_vec())),
            (b"T", Object::String(b"Ken".to_vec())),
            (b"Contents", Object::String(b"check this".to_vec())),
            (b"Subj", Object::String(b"Review".to_vec())),
            (
                b"CreationDate",
                Object::String(b"D:20260817120000Z".to_vec()),
            ),
            (b"IRT", Object::Reference(ObjId::new(99, 0))),
            (b"RT", Object::Name(Name::from(b"R"))),
            (b"StructParent", Object::Integer(4)),
        ] {
            seeded.insert(Name(k.to_vec()), v);
        }
        poke(&mut s, annot_id, Object::Dict(seeded.clone()));

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                width: Some(6.0),
                ..MarkupStyle::default()
            },
        )
        .unwrap();

        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        for key in [
            &b"NM"[..],
            b"T",
            b"Contents",
            b"Subj",
            b"CreationDate",
            b"IRT",
            b"RT",
            b"StructParent",
            b"P",
            b"F",
        ] {
            assert_eq!(
                after.get(key),
                seeded.get(key),
                "/{} must survive a restyle",
                String::from_utf8_lossy(key)
            );
        }
    }

    #[test]
    fn a_ce_dimension_is_refused_by_name_not_flattened_to_a_line() {
        // A ce dimension is a /Line with /IT /LineDimension and a baked
        // /AP that draws witness lines, terminators and a measured label.
        // It passes every "markup pdfce can author" test and would
        // regenerate as a BARE LINE — the label silently gone from
        // something the operator asked only to recolour.
        let mut s = session(pdf_without_info());
        let annot_id = s
            .add_markup(
                0,
                &MarkupSpec::Line {
                    start: (10.0, 10.0),
                    end: (90.0, 10.0),
                    color: Color::Rgb(0.0, 0.0, 0.0),
                    width: 1.0,
                    endings: (
                        crate::annot_author::LineEnding::None,
                        crate::annot_author::LineEnding::None,
                    ),
                },
            )
            .unwrap();
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            panic!("annot");
        };
        let mut dim = annot.clone();
        dim.insert(
            Name::from(b"IT"),
            Object::Name(Name::from(b"LineDimension")),
        );
        poke(&mut s, annot_id, Object::Dict(dim));

        let err = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(1.0, 0.0, 0.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap_err();
        assert!(matches!(err, EditError::AnnotationIsCeDimension { .. }));
    }

    /// ★ The `/IT` half of `is_ce_dimension`, ISOLATED from the sidecar half.
    ///
    /// The sibling above pokes `/IT /LineDimension` onto a plain markup
    /// annotation precisely so the sidecar cannot be what catches it — the
    /// annotation is not in the dimension model at all. This does the same for
    /// the two intents `Pass 107.0` introduced.
    ///
    /// Without it, the widening is untested: a perimeter authored the normal
    /// way IS in the sidecar, so a test built on one passes with the `/IT`
    /// arm removed and proves nothing about it. That is the difference between
    /// a test that covers a guard and a test that merely runs beside it.
    ///
    /// The case is real rather than contrived: a document whose sidecar was
    /// written by a NEWER pdfce, or stripped by another product, has ce
    /// dimensions this build's model cannot see — and their `/IT` is still on
    /// the page.
    #[test]
    fn a_perimeter_intent_alone_is_enough_to_refuse_a_restyle() {
        for intent in [&b"PolygonDimension"[..], &b"PolyLineDimension"[..]] {
            let mut s = session(pdf_without_info());
            let annot_id = s
                .add_markup(
                    0,
                    &MarkupSpec::Line {
                        start: (10.0, 10.0),
                        end: (90.0, 10.0),
                        color: Color::Rgb(0.0, 0.0, 0.0),
                        width: 1.0,
                        endings: (
                            crate::annot_author::LineEnding::None,
                            crate::annot_author::LineEnding::None,
                        ),
                    },
                )
                .unwrap();
            let Some(Object::Dict(annot)) = s.value(annot_id) else {
                panic!("annot");
            };
            let mut dim = annot.clone();
            dim.insert(Name::from(b"IT"), Object::Name(Name(intent.to_vec())));
            poke(&mut s, annot_id, Object::Dict(dim));

            let err = s
                .set_markup_style(
                    annot_id,
                    &MarkupStyle {
                        stroke: Some(StyleEdit::Set(Color::Rgb(1.0, 0.0, 0.0))),
                        ..MarkupStyle::default()
                    },
                )
                .unwrap_err();
            assert!(
                matches!(err, EditError::AnnotationIsCeDimension { .. }),
                "intent {} must refuse, got {err:?}",
                String::from_utf8_lossy(intent)
            );
        }
    }

    /// ★ The SIDECAR half of `is_ce_dimension`, isolated the other way.
    ///
    /// A REAL perimeter ce dimension with its `/IT` removed — the case where a
    /// third product rewrote or dropped the intent hint (§12.5.6.9 calls `/IT`
    /// a hint a reader may ignore, so a rewriter is within its rights). The
    /// `/IT` arm cannot see this one; the `/PieceInfo` sidecar can, because
    /// the annotation's object id is recorded against the ce dimension.
    ///
    /// Written because the previous two tests both pass with this arm removed:
    /// a poked markup annotation is not in the sidecar, and a real perimeter
    /// carries `/IT`. Claiming both arms are load-bearing and testing only one
    /// is the kind of half-verification this project has a rule about.
    #[test]
    fn a_ce_dimension_whose_intent_was_stripped_is_still_refused() {
        use crate::dimension::{DEFAULT_GROUP_ID, DimensionKind};
        use crate::vector::Point;

        let mut s = session(pdf_without_info());
        let (annot_id, _dim) = s
            .add_dimension(
                0,
                DEFAULT_GROUP_ID,
                DimensionKind::Perimeter {
                    points: vec![
                        Point::new(20.0, 20.0),
                        Point::new(80.0, 20.0),
                        Point::new(80.0, 60.0),
                    ],
                    closed: true,
                    offset: 0.0,
                    text_along: 0.0,
                },
            )
            .unwrap();
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            panic!("annot");
        };
        let mut stripped = annot.clone();
        stripped.remove(b"IT");
        poke(&mut s, annot_id, Object::Dict(stripped));

        let err = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(1.0, 0.0, 0.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap_err();
        assert!(
            matches!(err, EditError::AnnotationIsCeDimension { .. }),
            "the sidecar must still recognise it, got {err:?}"
        );
    }

    /// ★ R83: a setting is a promise. `quad_point_order` was parsed,
    /// validated and written back for its whole life, and READ BY NOTHING —
    /// an operator who chose `counterclockwise` got reading order anyway.
    ///
    /// The two orders differ only in the LAST TWO corner pairs: reading order
    /// ends `LL, LR`, the counterclockwise walk §12.5.6.10 describes ends
    /// `LR, LL`. This asserts exactly that swap in the written `/QuadPoints`,
    /// so it fails the moment the session stops consulting its own setting.
    ///
    /// It also pins the half that must NOT change: the baked `/AP` content is
    /// byte-identical under both orders, because the quads are drawn from the
    /// same four corners either way. If that ever diverged, switching a
    /// preference would silently alter how existing markup LOOKS, which is a
    /// different and much worse feature than the one being offered.
    #[test]
    fn the_quad_point_order_setting_reaches_the_written_annotation() {
        use crate::annot_author::{Color, MarkupSpec, Quad, TextMarkupKind};
        use crate::page_tree::Rect;
        use crate::settings::QuadPointOrder;

        let spec = MarkupSpec::TextMarkup {
            kind: TextMarkupKind::Highlight,
            quads: vec![Quad::from_rect(Rect {
                llx: 10.0,
                lly: 20.0,
                urx: 90.0,
                ury: 60.0,
            })],
            color: Color::Rgb(1.0, 1.0, 0.0),
        };

        let mut written = Vec::new();
        let mut appearances = Vec::new();
        for order in [
            QuadPointOrder::ReadingOrder,
            QuadPointOrder::Counterclockwise,
        ] {
            let mut s = session(pdf_without_info());
            s.set_quad_point_order(order);
            assert_eq!(s.quad_point_order(), order);
            let annot_id = s.add_markup(0, &spec).unwrap();
            let Some(Object::Dict(annot)) = s.value(annot_id) else {
                panic!("annot");
            };
            let quads: Vec<f64> = annot
                .get(b"QuadPoints")
                .and_then(Object::as_array)
                .expect("/QuadPoints")
                .iter()
                .map(|o| o.as_number().expect("number"))
                .collect();
            let ap_id = annot
                .get(b"AP")
                .and_then(Object::as_dict)
                .and_then(|d| d.get(b"N"))
                .and_then(Object::as_reference)
                .expect("/AP /N");
            let Some(Object::Stream(ap)) = s.value(ap_id) else {
                panic!("ap");
            };
            // The staged appearance content: `stage_bytes` addresses in the
            // combined `base.len() + local` coordinate system, so subtract the
            // base length to index the staging buffer.
            let start = ap.data_span.start - s.base.bytes().len();
            appearances.push(s.staging[start..start + ap.data_span.len].to_vec());
            written.push(quads);
        }

        let (reading, ccw) = (&written[0], &written[1]);
        assert_eq!(reading.len(), 8, "one quad, eight numbers");
        // The first two corners (UL, UR) are identical under both orders.
        assert_eq!(reading[0..4], ccw[0..4], "UL and UR must not move");
        // The last two are SWAPPED, in pairs.
        assert_eq!(reading[4..6], ccw[6..8], "reading LL must be ccw's last");
        assert_eq!(reading[6..8], ccw[4..6], "reading LR must be ccw's third");
        assert_ne!(
            reading, ccw,
            "the setting must reach the file at all — this is the R83 half"
        );
        assert_eq!(
            appearances[0], appearances[1],
            "the baked /AP must be byte-identical: this changes what /QuadPoints says, never how the markup looks"
        );
    }

    #[test]
    fn an_unmodelled_subtype_is_refused_rather_than_guessed() {
        // FreeText, Stamp, Widget, Link — pdfce has no authoring model
        // for their appearances, so regenerating one would mean inventing
        // it.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /FreeText /Rect [10 10 100 40] /DA (/Helv 0 Tf 0 g) >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let err = s
            .set_markup_style(ObjId::new(4, 0), &MarkupStyle::default())
            .unwrap_err();
        assert!(
            matches!(
                &err,
                EditError::MarkupSpec(crate::annot_author::SpecReadError::UnsupportedSubtype {
                    subtype
                }) if subtype == "FreeText"
            ),
            "got {err:?}"
        );
        assert!(!s.is_modified());
    }

    #[test]
    fn missing_geometry_is_refused_rather_than_invented() {
        // A /Polygon with no /Vertices has nothing to draw. Inventing a
        // shape for it is exactly what rule 4 forbids.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /Polygon /Rect [10 10 100 40] /C [1 0 0] >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let err = s
            .set_markup_style(ObjId::new(4, 0), &MarkupStyle::default())
            .unwrap_err();
        assert!(
            matches!(
                err,
                EditError::MarkupSpec(crate::annot_author::SpecReadError::BadGeometry {
                    key: "Vertices"
                })
            ),
            "got {err:?}"
        );
    }

    #[test]
    fn a_shared_appearance_is_copied_not_rewritten() {
        // §12.5.2: the one-page rule "applies only to the annotation
        // dictionary itself, NOT to subsidiary objects, which may be
        // shared". Rewriting a shared /AP in place would restyle an
        // annotation the operator never selected — silently, on whichever
        // page it happens to be.
        let mut s = session(pdf_without_info());
        let first = s.add_markup(0, &square_spec()).unwrap();
        let second = s.add_markup(0, &square_spec()).unwrap();
        let shared_ap = ap_of(&s, first).expect("AP");

        // Point the second annotation at the first's appearance.
        let Some(Object::Dict(annot)) = s.value(second) else {
            panic!("annot");
        };
        let mut aliased = annot.clone();
        let mut ap = Dict::new();
        ap.insert(Name::from(b"N"), Object::Reference(shared_ap));
        aliased.insert(Name::from(b"AP"), Object::Dict(ap));
        poke(&mut s, second, Object::Dict(aliased));
        let Some(shared_before) = s.value(shared_ap).cloned() else {
            panic!("shared AP");
        };

        let change = s
            .set_markup_style(
                second,
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 1.0, 0.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();

        let AppearanceWrite::CopiedOnWrite { from, to } = change.appearance else {
            panic!("expected copy-on-write, got {:?}", change.appearance);
        };
        assert_eq!(from, shared_ap);
        assert_ne!(to, shared_ap);
        assert_eq!(
            s.value(shared_ap).cloned(),
            Some(shared_before),
            "the OTHER annotation's appearance must be untouched"
        );
        assert_eq!(
            ap_of(&s, first),
            Some(shared_ap),
            "and it still points at it"
        );
        assert_eq!(ap_of(&s, second), Some(to));
    }

    #[test]
    fn an_annotation_with_no_appearance_gets_one_created() {
        // R43 means an annotation with no /AP does not paint at all.
        // Restyling it is how it starts to.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /Square /Rect [10 10 100 40] /C [1 0 0] >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let change = s
            .set_markup_style(
                ObjId::new(4, 0),
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert!(matches!(change.appearance, AppearanceWrite::Created(_)));
        assert!(ap_of(&s, ObjId::new(4, 0)).is_some());
        assert!(
            change.dropped.is_empty(),
            "nothing was replaced, so nothing was lost: {:?}",
            change.dropped
        );
    }

    #[test]
    fn restyling_discloses_what_the_regeneration_dropped() {
        // Rule 4: the appearance no longer draws a cloudy border or a
        // dashed stroke, even though the dictionary keys survive. Named,
        // not left for the operator to notice.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /Square /Rect [10 10 100 40] /C [1 0 0] \
                 /BE << /S /C /I 2 >> /RD [2 2 2 2] \
                 /BS << /W 3 /S /D /D [3 2] >> \
                 /AP << /N 5 0 R >> >>",
                "<< /Length 1 >>
stream
 
endstream",
            ],
            "",
        );
        let mut s = session(bytes);
        let change = s
            .set_markup_style(
                ObjId::new(4, 0),
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();

        for expected in [
            DroppedProperty::RectDifferences,
            DroppedProperty::BorderStyle,
            DroppedProperty::DashPattern,
            DroppedProperty::ForeignAppearance,
        ] {
            assert!(
                change.dropped.contains(&expected),
                "{expected:?} must be disclosed; got {:?}",
                change.dropped
            );
        }
        // ★ `BorderEffect` USED TO BE IN THAT LIST, and its removal is the
        // point of `Pass 98.0`. This fixture's `/BE << /S /C /I 2 >>` on a
        // `/Square` is now READ BACK and re-baked, so disclosing it as
        // dropped would be a FALSE disclosure.
        //
        // Rule 4 cuts both ways: a reported loss that did not happen trains
        // the operator to discount the four above, which did.
        assert!(
            !change.dropped.contains(&DroppedProperty::BorderEffect),
            "a cloudy /BE on a /Square is preserved now, so it must NOT be \
             reported as dropped; got {:?}",
            change.dropped
        );
    }

    /// The cases where `/BE` is still genuinely lost, so the disclosure is
    /// still owed.
    ///
    /// The companion to the assertion above, and the reason it is a separate
    /// test rather than another line in that one: "we stopped reporting a
    /// loss" is only correct if we still report the losses that remain.
    /// Removing a disclosure is the kind of change that is easy to take too
    /// far, and this is what bounds it.
    #[test]
    fn a_border_effect_pdfce_cannot_carry_is_still_disclosed() {
        // A `/Circle` has no `border_effect` in pdfce's spec at all, and a
        // `/Square` whose `/S` is the Table 167 SOLID default is not a cloud
        // — reading one as a cloud would invent a shape the file does not
        // describe.
        for (subtype, be) in [
            ("Circle", "<< /S /C /I 1 >>"),
            ("Square", "<< /S /S >>"),
            ("Square", "<< /S /Something /I 1 >>"),
        ] {
            let bytes = build(
                &[
                    "<< /Type /Catalog /Pages 2 0 R >>",
                    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                     /Annots [4 0 R] >>",
                    &format!(
                        "<< /Type /Annot /Subtype /{subtype} /Rect [10 10 100 40] \
                         /C [1 0 0] /BE {be} >>"
                    ),
                ],
                "",
            );
            let mut s = session(bytes);
            let change = s
                .set_markup_style(
                    ObjId::new(4, 0),
                    &MarkupStyle {
                        stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                        ..MarkupStyle::default()
                    },
                )
                .unwrap();
            assert!(
                change.dropped.contains(&DroppedProperty::BorderEffect),
                "/{subtype} with /BE {be} loses the effect and must SAY so; \
                 got {:?}",
                change.dropped
            );
        }
    }

    /// ★ THE ROUND TRIP the Pass was scoped on: a foreign revision cloud,
    /// restyled, still LOOKS like a cloud.
    ///
    /// # ★★ THIS TEST ASSERTED THE WRONG THING FIRST, and a sabotage run is
    /// what caught it
    ///
    /// The Pass's own acceptance sketch said *"verify `/BE` survives"*, and
    /// the first version of this test did exactly that — read `/BE` back out
    /// of the dictionary and checked `/S /C` and `/I`.
    ///
    /// **It passed with the reader stubbed out to return `None`.** Of course
    /// it did: `set_markup_style` patches the properties it edits, so `/BE`
    /// was never being deleted. The defect was never a missing key — it was
    /// that *the annotation said cloud and the appearance drew flat*. A
    /// dictionary assertion cannot see that, which is exactly why the
    /// operator's report would have been "why did my cloud go flat?" and not
    /// "why did my `/BE` vanish?".
    ///
    /// So this checks the APPEARANCE, differentially: the same polygon with
    /// and without `/BE` must restyle to **different** appearance streams,
    /// and the cloudy one must be drawn with curves. Either assertion alone
    /// is weak — a curve could come from elsewhere, and two streams could
    /// differ for a trivial reason — and together they are hard to satisfy
    /// by accident.
    #[test]
    fn a_foreign_revision_cloud_survives_a_restyle() {
        fn restyled_appearance(be: &str) -> Vec<u8> {
            let annot = format!(
                "<< /Type /Annot /Subtype /Polygon /Rect [10 10 200 120] \
                 /Vertices [20 20 180 20 180 100 20 100] /C [1 0 0] {be} >>"
            );
            let bytes = build(
                &[
                    "<< /Type /Catalog /Pages 2 0 R >>",
                    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] \
                     /Resources << >> /Annots [4 0 R] >>",
                    &annot,
                ],
                "",
            );
            let mut s = session(bytes);
            s.set_markup_style(
                ObjId::new(4, 0),
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .expect("restyle succeeds");

            let view = s.view();
            let Object::Dict(a) = view.resolved(ObjId::new(4, 0)) else {
                panic!("the annotation must still be a dictionary");
            };
            let Some(Object::Dict(ap)) = a.get(b"AP").map(|o| view.resolve(o)) else {
                panic!("a restyle must leave a baked /AP (R43)");
            };
            let Some(Object::Reference(n_ref)) = ap.get(b"N") else {
                panic!("/AP /N must be an indirect stream");
            };
            let Object::Stream(st) = view.resolved(*n_ref) else {
                panic!("/AP /N must resolve to a stream");
            };
            view.slice(st.data_span).expect("appearance bytes").to_vec()
        }

        let cloudy = restyled_appearance("/BE << /S /C /I 1.5 >>");
        let plain = restyled_appearance("");

        assert_ne!(
            cloudy, plain,
            "a cloudy polygon and a plain one must NOT restyle to the same \
             appearance — identical bytes mean the cloud was flattened, which \
             is the whole defect Pass 98.0 fixes"
        );

        // A scalloped border is drawn with curves; a straight outline is not.
        // Matched as a whole operator (space-c-newline or space-c-space) so a
        // `c` inside a name or a number cannot satisfy it.
        let curves = cloudy
            .windows(3)
            .filter(|w| w[0] == b' ' && w[1] == b'c' && (w[2] == b'\n' || w[2] == b' '))
            .count();
        assert!(
            curves > 8,
            "a cloudy border must be drawn with curve operators; found \
             {curves} in {} bytes of appearance",
            cloudy.len()
        );
    }

    #[test]
    fn restyling_pdfces_own_markup_reports_no_loss() {
        // The centre case, and the one a blunt always-on flag got wrong:
        // recolouring a square pdfce authored seconds earlier must NOT
        // warn about shadows and gradients. A disclosure that fires on
        // the common path is one an operator learns to skip, which spends
        // the credibility the genuinely-lossy case needs.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let change = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert!(
            change.dropped.is_empty(),
            "regenerating pdfce's own appearance is provably lossless: {:?}",
            change.dropped
        );

        // And restyling the RESULT is still lossless -- the regenerated
        // stream has to be recognisable on the next pass too, or the
        // second colour change would suddenly start warning.
        let again = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    width: Some(5.0),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert!(again.dropped.is_empty(), "{:?}", again.dropped);
    }

    #[test]
    fn restyling_a_foreign_appearance_reports_the_loss() {
        // The other half of the same measurement: an /AP whose bytes are
        // not what pdfce would have drawn from these properties IS
        // reported, so the precise version has not simply gone quiet.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> /Annots \
                 [4 0 R] >>",
                "<< /Type /Annot /Subtype /Square /Rect [10 10 100 40] /C [1 0 0] /AP << /N 5 0 \
                 R >> >>",
                "<< /Length 22 >>
stream
0 0 1 rg 1 1 8 8 re f
endstream",
            ],
            "",
        );
        let mut s = session(bytes);
        let change = s
            .set_markup_style(
                ObjId::new(4, 0),
                &MarkupStyle {
                    stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert!(
            change.dropped.contains(&DroppedProperty::ForeignAppearance),
            "a hand-authored appearance must be reported: {:?}",
            change.dropped
        );
    }

    #[test]
    fn an_exotic_line_ending_is_disclosed_rather_than_silently_flattened() {
        // `spec_from_dict` degrades an unmodelled /LE to None so the
        // recolour can still happen — which is exactly why the loss has
        // to be detected against the FILE and reported.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /Line /Rect [10 10 100 40] /L [10 10 100 40] \
                 /C [1 0 0] /LE [/Diamond /ClosedArrow] >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let change = s
            .set_markup_style(
                ObjId::new(4, 0),
                &MarkupStyle {
                    width: Some(2.0),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert!(change.dropped.contains(&DroppedProperty::LineEnding));
        // The ending pdfce DOES author survives.
        let Some(Object::Dict(after)) = s.value(ObjId::new(4, 0)) else {
            panic!("annot");
        };
        let Some(Object::Array(le)) = after.get(b"LE") else {
            panic!("/LE");
        };
        assert_eq!(le.len(), 2);
        assert_eq!(
            le[1].as_name().map(|n| n.as_bytes().to_vec()),
            Some(b"ClosedArrow".to_vec())
        );
    }

    #[test]
    fn widening_a_line_moves_its_rect_and_that_is_correct() {
        // For every subtype except Square/Circle the /Rect is DERIVED
        // from the geometry plus a margin containing the stroke and any
        // arrowheads. A wider pen needs a bigger box; the change is
        // reported rather than being a surprise.
        let mut s = session(pdf_without_info());
        let annot_id = s
            .add_markup(
                0,
                &MarkupSpec::Line {
                    start: (10.0, 10.0),
                    end: (90.0, 10.0),
                    color: Color::Rgb(0.0, 0.0, 0.0),
                    width: 1.0,
                    endings: (
                        crate::annot_author::LineEnding::None,
                        crate::annot_author::LineEnding::None,
                    ),
                },
            )
            .unwrap();
        let change = s
            .set_markup_style(
                annot_id,
                &MarkupStyle {
                    width: Some(12.0),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        let before = change.rect_before.expect("rect");
        assert!(
            change.rect_after.height() > before.height(),
            "a 12pt pen needs a taller box than a 1pt one: {before:?} -> {:?}",
            change.rect_after
        );
        // And a Square's rect is NOT derived, so it does not move.
        let sq = s.add_markup(0, &square_spec()).unwrap();
        let change = s
            .set_markup_style(
                sq,
                &MarkupStyle {
                    width: Some(12.0),
                    ..MarkupStyle::default()
                },
            )
            .unwrap();
        assert_eq!(change.rect_before, Some(change.rect_after));
    }

    #[test]
    fn clearing_an_optional_colour_removes_the_key() {
        // "No border" is a real style and §12.5.6 spells it as an ABSENT
        // /C — there is no transparent value in a DeviceRGB array. This
        // is why StyleEdit has a Clear variant at all.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Clear),
                interior: Some(StyleEdit::Set(Color::Rgb(1.0, 1.0, 0.0))),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        assert!(after.get(b"C").is_none(), "/C must be removed, not zeroed");
        assert!(after.get(b"IC").is_some());
    }

    #[test]
    fn clearing_a_required_colour_falls_back_to_black_not_invisible() {
        // A /Line's stroke is unconditional (§12.5.6.7). "Clear" there
        // cannot mean "draw nothing" — that is an annotation the operator
        // can no longer find.
        let mut s = session(pdf_without_info());
        let annot_id = s
            .add_markup(
                0,
                &MarkupSpec::Line {
                    start: (10.0, 10.0),
                    end: (90.0, 10.0),
                    color: Color::Rgb(1.0, 0.0, 0.0),
                    width: 1.0,
                    endings: (
                        crate::annot_author::LineEnding::None,
                        crate::annot_author::LineEnding::None,
                    ),
                },
            )
            .unwrap();
        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Clear),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        assert_eq!(color_of(&s, annot_id), vec![0.0], "DeviceGray black");
    }

    #[test]
    fn a_colour_only_restyle_keeps_every_other_property() {
        // The defect a sabotage found this file blind to: if
        // `spec_from_dict` ignored /BS /W, changing only the COLOUR would
        // regenerate the appearance at the default 1pt and silently thin
        // a 7pt border. Nothing the operator asked for, nothing reported.
        // The same argument applies to the interior and the endings, so
        // all three are held here.
        let mut s = session(pdf_without_info());
        let annot_id = s
            .add_markup(
                0,
                &MarkupSpec::Square {
                    rect: Rect {
                        llx: 20.0,
                        lly: 20.0,
                        urx: 120.0,
                        ury: 70.0,
                    },
                    border: Some(Color::Rgb(1.0, 0.0, 0.0)),
                    interior: Some(Color::Rgb(0.0, 1.0, 0.0)),
                    border_width: 7.0,
                    border_effect: None,
                },
            )
            .unwrap();

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                ..MarkupStyle::default()
            },
        )
        .unwrap();

        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        let Some(Object::Dict(bs)) = after.get(b"BS") else {
            panic!("/BS");
        };
        assert_eq!(
            bs.get(b"W").and_then(Object::as_number),
            Some(7.0),
            "the border width must survive a colour-only change"
        );
        assert_eq!(
            after.get(b"IC").and_then(Object::as_array).map(|a| a.len()),
            Some(3),
            "the interior colour must survive too"
        );
        // And the appearance stream is regenerated AT that width, not at
        // the default -- a dictionary that says 7 over an appearance drawn
        // at 1 is the R43 disagreement this verb exists to avoid.
        let ap = ap_of(&s, annot_id).expect("AP");
        assert!(
            String::from_utf8_lossy(&ap_bytes(&s, ap)).contains("7 w"),
            "appearance: {}",
            String::from_utf8_lossy(&ap_bytes(&s, ap))
        );
    }

    #[test]
    fn a_width_only_restyle_keeps_the_line_endings() {
        // Same shape, for /LE: `spec_from_dict` has to read the arrowheads
        // back or a width tweak would silently remove them.
        let mut s = session(pdf_without_info());
        let annot_id = s
            .add_markup(
                0,
                &MarkupSpec::Line {
                    start: (10.0, 10.0),
                    end: (90.0, 10.0),
                    color: Color::Rgb(0.0, 0.0, 0.0),
                    width: 1.0,
                    endings: (
                        crate::annot_author::LineEnding::ClosedArrow,
                        crate::annot_author::LineEnding::OpenArrow,
                    ),
                },
            )
            .unwrap();
        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                width: Some(3.0),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        let Some(Object::Array(le)) = after.get(b"LE") else {
            panic!("/LE");
        };
        assert_eq!(
            le.iter()
                .filter_map(|o| o.as_name().map(|n| n.as_bytes().to_vec()))
                .collect::<Vec<_>>(),
            vec![b"ClosedArrow".to_vec(), b"OpenArrow".to_vec()]
        );
    }

    #[test]
    fn opacity_sets_and_clears_ca() {
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                opacity: Some(StyleEdit::Set(0.4)),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        assert_eq!(after.get(b"CA").and_then(Object::as_number), Some(0.4));

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                opacity: Some(StyleEdit::Clear),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        let Some(Object::Dict(after)) = s.value(annot_id) else {
            panic!("annot");
        };
        assert!(
            after.get(b"CA").is_none(),
            "absent /CA is §12.5.2's fully-opaque, and differs from an explicit 1.0"
        );
    }

    #[test]
    fn restyling_is_one_undo_entry_and_undo_restores_the_bytes() {
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let before = s.value(annot_id).cloned();
        let depth = s.undo_depth();

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                width: Some(9.0),
                ..MarkupStyle::default()
            },
        )
        .unwrap();
        assert_eq!(s.undo_depth(), depth + 1, "one entry for the whole restyle");
        assert_eq!(s.undo_kind(), Some(CommandKind::SetMarkupStyle));
        assert!(s.undo().is_some());
        assert_eq!(s.value(annot_id).cloned(), before);
    }

    #[test]
    fn restyling_never_touches_the_page_content_stream() {
        // R47: annotations live in /Annots and their own appearance
        // streams. An annotation edit that rewrote page content would be
        // a minimal-diff violation with no upside.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let dirty_before: Vec<ObjId> = s.dirty_set().iter().collect();

        s.set_markup_style(
            annot_id,
            &MarkupStyle {
                stroke: Some(StyleEdit::Set(Color::Rgb(0.0, 0.0, 1.0))),
                ..MarkupStyle::default()
            },
        )
        .unwrap();

        // The restyle added no object to the dirty set beyond the two it
        // owns (annotation + its own appearance), both of which the add
        // had already dirtied.
        let dirty_after: Vec<ObjId> = s.dirty_set().iter().collect();
        assert_eq!(
            dirty_before.len(),
            dirty_after.len(),
            "a restyle over pdfce's own markup writes nothing new"
        );
    }

    #[test]
    fn a_locked_annotation_refuses_a_restyle() {
        // §12.5.3 Table 165 bit 8 — the same clause `delete_annotation`
        // honours. "Locked" is exactly about the user interface not
        // changing properties.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            panic!("annot");
        };
        let mut locked = annot.clone();
        locked.insert(
            Name::from(b"F"),
            Object::Integer(i64::from(AnnotFlags::LOCKED)),
        );
        poke(&mut s, annot_id, Object::Dict(locked));

        let err = s
            .set_markup_style(annot_id, &MarkupStyle::default())
            .unwrap_err();
        assert!(matches!(err, EditError::AnnotationLocked { .. }));
    }

    #[test]
    fn an_appearance_state_subdictionary_is_refused() {
        // §12.5.5 Table 168: an /AP /N may be a subdictionary of states
        // selected by /AS. Regenerating would have to pick one to rewrite
        // and leave the others describing a different style.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << >> \
                 /Annots [4 0 R] >>",
                "<< /Type /Annot /Subtype /Square /Rect [10 10 100 40] /C [1 0 0] \
                 /AS /On /AP << /N << /On 5 0 R /Off 5 0 R >> >> >>",
                "<< /Length 0 >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let err = s
            .set_markup_style(ObjId::new(4, 0), &MarkupStyle::default())
            .unwrap_err();
        assert!(
            matches!(err, EditError::AppearanceHasStates { .. }),
            "got {err:?}"
        );
    }

    #[test]
    fn an_empty_style_still_regenerates_and_reports() {
        // Not a no-op, and deliberately so: an empty override on an
        // annotation with a foreign /AP is how a caller says "redraw this
        // from its declared properties". The report says what that cost.
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let change = s
            .set_markup_style(annot_id, &MarkupStyle::default())
            .unwrap();
        assert_eq!(change.annot_id, annot_id);
        assert!(MarkupStyle::default().is_empty());
    }

    #[test]
    fn set_markup_style_names_an_annotation_that_is_not_there() {
        let mut s = session(pdf_without_info());
        let err = s
            .set_markup_style(ObjId::new(404, 0), &MarkupStyle::default())
            .unwrap_err();
        assert!(matches!(err, EditError::AnnotationNotFound { .. }));
    }

    #[test]
    fn adding_a_markup_creates_appearance_annotation_and_patches_annots() {
        // One gesture ⇒ appearance stream + annotation dict + /Annots patch,
        // all in one command (§11.3, R49).
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        assert!(s.is_modified());
        assert_eq!(s.undo_depth(), 1, "one undo entry for the whole gesture");

        // The annotation dict is present, geometry + AP wired.
        let Some(Object::Dict(annot)) = s.value(annot_id) else {
            panic!("annotation not created");
        };
        assert_eq!(
            annot.get(b"Subtype").unwrap().as_name().unwrap().as_bytes(),
            b"Square"
        );
        assert!(annot.get(b"AP").is_some(), "R44: a full /AP is baked");
        assert!(annot.get(b"P").is_some(), "back-reference to the page");

        // The page's /Annots now references it (page 3 in pdf_without_info).
        let Some(Object::Dict(page)) = s.value(ObjId::new(3, 0)) else {
            panic!("page missing");
        };
        let Some(Object::Array(annots)) = page.get(b"Annots") else {
            panic!("/Annots not created as an array");
        };
        assert_eq!(annots.len(), 1);
        assert_eq!(annots[0].as_reference(), Some(annot_id));
    }

    #[test]
    fn authored_appearance_survives_save_reload_byte_exact_r44() {
        // R44 round-trip: author → save → reload → the /AP /N stream's
        // decoded bytes equal what the generator emitted, and Pass 6.0
        // selects it as the normal appearance.
        let expected = {
            let a = crate::annot_author::build_appearance(&square_spec());
            a.ap_content
        };
        let mut s = session(pdf_without_info());
        let annot_id = s.add_markup(0, &square_spec()).unwrap();
        let (bytes, _report) = s
            .to_incremental_bytes(&crate::writer::SaveOptions::identity())
            .unwrap();

        let reloaded = Document::from_bytes(bytes).unwrap();
        // The reloaded annotation still resolves a usable normal appearance.
        let annots = crate::annot::page_annotations(&reloaded, ObjId::new(3, 0));
        assert_eq!(annots.len(), 1);
        let ap_id = match &annots[0].appearance {
            crate::annot::Appearance::Normal { stream_id } => stream_id.unwrap(),
            other => panic!("expected a normal appearance, got {other:?}"),
        };
        // Its content bytes survived the staging → save → reload path exact.
        let Some(io) = reloaded.get(ap_id) else {
            panic!("appearance stream missing after reload");
        };
        let Object::Stream(stream) = &io.value else {
            panic!("appearance is not a stream");
        };
        let raw = stream.data_span.slice(reloaded.bytes()).unwrap();
        let decoded = crate::filters::decode_stream(&stream.dict, raw).unwrap();
        assert_eq!(decoded, expected, "authored appearance bytes must survive");
        // The annotation id we created is the one referenced (basic sanity).
        assert!(reloaded.get(annot_id).is_some());
    }

    #[test]
    fn undo_of_authoring_removes_everything_and_empties_the_dirty_set() {
        let mut s = session(pdf_without_info());
        s.add_markup(0, &square_spec()).unwrap();
        assert!(!s.dirty_set().is_empty());
        s.undo();
        assert!(!s.is_modified(), "undo of authoring nets to nothing");
        assert!(s.dirty_set().is_empty());
        // The page's /Annots patch is gone too (the page reads through to
        // the base, which had no /Annots).
        let Some(Object::Dict(page)) = s.value(ObjId::new(3, 0)) else {
            panic!("page missing");
        };
        assert!(page.get(b"Annots").is_none());
    }

